-- Public service-page copy, editable by invitation-only account users.
create table public.service_page_content (
  page_key text primary key check (page_key in ('charters', 'transportation')),
  content jsonb not null check (jsonb_typeof(content) = 'object' and octet_length(content::text) <= 150000),
  updated_at timestamptz not null default now()
);

create function public.touch_service_page_content_updated_at() returns trigger
language plpgsql set search_path = '' as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create trigger service_page_content_updated_at
before update on public.service_page_content
for each row execute function public.touch_service_page_content_updated_at();

alter table public.service_page_content enable row level security;
revoke all on public.service_page_content from anon, authenticated;
grant select on public.service_page_content to anon, authenticated;
grant insert, update on public.service_page_content to authenticated;

create policy "Visitors read service page content"
on public.service_page_content for select to anon, authenticated using (true);

create policy "Account users create service page content"
on public.service_page_content for insert to authenticated with check (true);

create policy "Account users update service page content"
on public.service_page_content for update to authenticated using (true) with check (true);

insert into public.service_page_content (page_key, content) values
  ('charters', $content${"infoTabs":[{"id":"why","label":"Why X-Yachts","paragraphs":["Sailing is not just about moving from one port to another—it is about how the journey feels beneath your hands and under your feet. Founded in Denmark in 1979, X-Yachts has built a legacy of more than four decades defined by an unyielding commitment to supreme build quality, structural integrity, and uncompromising safety at sea. Crafted with extreme precision, every yacht reflects the craftsmanship of the Danish naval industry.","Choosing X-Yachting means gaining access to an exclusive fleet, including flagship cruisers like the Xc 47 and race-proven champions like the XR 41, which continues to dominate prestigious podiums in world-class competitions across the Baltic, Mediterranean, and Aegean seas.","Whether you are cutting through swell with effortless precision or relaxing in a meticulously engineered salon, every detail is designed to deliver an unmatched sailing experience. It is the ultimate opportunity to feel the responsiveness and safety of a world-class performance yacht in real Mediterranean conditions, whether for the vacation of a lifetime or the ultimate “try before you buy” journey."],"items":[]},{"id":"who","label":"Who is it for?","paragraphs":[],"items":[{"label":"For everyone","text":"Suitable for all levels, regardless of prior sailing experience."},{"label":"Families & friends","text":"Ideal for relaxed vacations, island-hopping, and authentic sailing comfort."},{"label":"Discerning & experienced sailors","text":"Perfect for those wanting to take full command of a luxury performance yacht."},{"label":"Competitive racers","text":"Tailored packages for offshore regattas, racing charters, and performance sailing in Greece."},{"label":"Day cruisers & speed enthusiasts","text":"Designed for guests seeking fast, comfortable motorboat day escapes or private transfers."}]},{"id":"when-where","label":"When & where?","paragraphs":["The Mediterranean season comes alive from March through November, offering a breathtaking canvas of sun-drenched days, steady Meltemi winds, and calm, crystalline waters. Starting your journey at Olympic Marine in Lavrio, Greece—just a 35-minute drive from Athens International Airport—you are positioned perfectly at the gateway to the Aegean.","Within just 16 nautical miles, the majestic Cyclades and Saronic Gulf open up before you: sail past the iconic ancient Temple of Poseidon perched high above Cape Sounion, explore the volcanic caldera and iconic cliffside villages of Santorini, anchor in the glamorous bays of Mykonos, discover the natural sea caves of Milos, drop anchor in secluded turquoise coves, and spend evenings in vibrant waterfront tavernas sampling local Greek culinary delicacies."],"items":[{"label":"Charter season","text":"March through November."},{"label":"Base location","text":"Olympic Marine, Lavrio, Greece (35 minutes from Athens International Airport)."},{"label":"Standard duration","text":"Saturday midday to Saturday morning (1, 2, 3, or more weeks). Flexible dates, short stays, and single-day escapes are also available."}]},{"id":"models","label":"Available models","paragraphs":[],"items":[{"label":"X-Yachts Xc 47","text":"The best cruiser X-Yachts has ever built, available for charter exclusively through X-Yachting worldwide."},{"label":"X-Yachts X4⁶","text":"A versatile family performance cruiser balancing speed, supreme comfort, and effortless handling for all skill levels."},{"label":"X-Yachts X4³ MkII","text":"Crafted with advanced technology for maximum structural strength, safety, and pure sailing pleasure."},{"label":"X-Yachts X4⁰","text":"A compact luxury performance yacht blending premium quality and style for long-distance cruising."},{"label":"X-Yachts XR 41","text":"The pinnacle of pure racing DNA—a race-ready champion designed for serious competitive charter racing, ORC regattas, and high-speed offshore passage-making without compromising performance."},{"label":"X-Yachts Xp 44","text":"The ultimate performance sailing yacht, engineered for speed, power, and easy short-handed handling."},{"label":"X-Power 33c","text":"A luxury powerboat (gentleman’s cruiser) built for high-speed day escapes, island-hopping, and sea transfers with unmatched quality."}]}],"skipperOptions":[{"id":"full-time","label":"Full-Time Skipper","description":"A professional skipper remains on board throughout your trip, providing safe handling, local knowledge, and an effortless, stress-free vacation."},{"id":"day-one","label":"Day-One Skipper","description":"A skipper joins you for the first day to familiarize you with the yacht’s systems, rig, and handling before handing over full command for your self-guided voyage."},{"id":"ghost","label":"Ghost Skipper","description":"A skipper stays on board in a discreet, supportive role—giving you hands-on control with expert guidance and skill refinement whenever you need it."},{"id":"bareboat","label":"Bareboat","description":"For experienced sailors with valid certifications who wish to take full command of the yacht, charting their own course and sailing at their own pace alongside family and friends."}]}$content$::jsonb),
  ('transportation', $content${"sections":[{"id":"road","heading":"Yacht Transport by Road","paragraphs":[{"lead":"","text":"Moving a yacht over land takes more than a truck. It takes planning, the right equipment, and people who understand boats. We handle the entire process, so your yacht arrives safely and ready to launch."},{"lead":"Door-to-door service.","text":"We collect your boat from the yard, marina or factory and deliver it to your chosen destination anywhere in Europe, including Turkey, Serbia, Montenegro and Albania."},{"lead":"Everything included.","text":"Route planning, oversize-load permits, escort vehicles where required, lashing, shrink-wrapping, and transit insurance with full coverage."},{"lead":"12 Hour update basis.","text":"Route planning, oversize-load permits, escort vehicles where required, mast unstepping and packing, cradles, lashing, shrink-wrapping, and transit insurance."},{"lead":"Full price transparency.","text":"No hidden fees or surprises. What we quote for is what you pay."}]},{"id":"sea","heading":"Yacht Transport by Sea","paragraphs":[{"lead":"","text":"Our staff are certified RYA sailors with multiple ocean crossings who will deliver your yacht anywhere in the world with minimal risk to the boat's condition. We specialise in sailing yachts up to 65 FT and powerboats up to 100 FT."},{"lead":"","text":"We provide safe, reliable, and fully managed boat and yacht transportation services worldwide. From coastal deliveries to transoceanic shipments, our experienced team ensures your vessel is handled with precision, care, and complete attention to detail."}]}]}$content$::jsonb)
 on conflict (page_key) do nothing;
